--- fuzzer dict ---
# IVF Signature + version (bytes 0-5)
kw1="DKIF\x00\x00"

# AV1 codec fourCC (bytes 8-11)
kw2="AV01"
--- build script ---
build_dir=$WORK/build
mkdir -p ${build_dir}
pushd ${build_dir}
rm -rf ./*
if [[ $CFLAGS = *sanitize=memory* ]]; then
  extra_c_flags='-DAOM_MAX_ALLOCABLE_MEMORY=536870912'
else
  extra_c_flags='-DAOM_MAX_ALLOCABLE_MEMORY=1073741824'
fi
extra_c_flags+=' -DDO_RANGE_CHECK_CLAMP=1'
extra_cmake_flags=
if [[ $CFLAGS = *sanitize=memory* ]]; then
  extra_cmake_flags+="-DAOM_TARGET_CPU=generic"
fi
cmake $SRC/aom -DCMAKE_BUILD_TYPE=Release -DCMAKE_C_FLAGS_RELEASE='-O3 -g'   -DCMAKE_CXX_FLAGS_RELEASE='-O3 -g' -DCONFIG_PIC=1 -DCONFIG_LOWBITDEPTH=1   -DCONFIG_AV1_ENCODER=0 -DENABLE_EXAMPLES=0 -DENABLE_DOCS=0 -DENABLE_TESTS=0   -DCONFIG_SIZE_LIMIT=1 -DDECODE_HEIGHT_LIMIT=12288 -DDECODE_WIDTH_LIMIT=12288   -DAOM_EXTRA_C_FLAGS="${extra_c_flags}"   -DAOM_EXTRA_CXX_FLAGS="${extra_c_flags}" ${extra_cmake_flags}
make -j$(nproc)
popd
fuzzer_src_name=av1_dec_fuzzer
fuzzer_name=${fuzzer_src_name}
$CXX $CXXFLAGS -std=c++11   -I$SRC/aom   -I${build_dir}   -Wl,--start-group   $LIB_FUZZING_ENGINE   $SRC/aom/examples/${fuzzer_src_name}.cc -o $OUT/${fuzzer_name}   ${build_dir}/libaom.a -Wl,--end-group
cp $SRC/dec_fuzzer_seed_corpus.zip $OUT/${fuzzer_name}_seed_corpus.zip
cp $SRC/av1_dec_fuzzer.dict $OUT/${fuzzer_name}.dict
